const $=s=>document.querySelector(s),app=$('#app'),params=new URLSearchParams(location.search);let db,auth,user,menus=[],selected='',current=null,view='dashboard',orders=[],cart=[],lang='ar',category='all',search='',modal=false,orderType='delivery';
