const fresh=()=>({name:{ar:'مطعم جديد',en:'New Restaurant'},description:{ar:'',en:''},owner:user?.uid||'',active:true,accent:'#f56a18',phone:'',categories:[],hours:{open:'09:00',close:'22:00'},orderSettings:{delivery:true,pickup:true,deliveryFee:0},design:{layout:'grid',rounded:true},logo:''});
