async function init(){if(!isReady()){app.innerHTML=`<div class="login-wrap"><div class="login-card">${brand}<h1>إعداد Firebase الحالي</h1><p>انسخ إعدادات Web App من Firebase Console إلى الملف <b>firebase-config.js</b> ثم انشر المشروع.</p><div class="notice">لم يتم تغيير أي بيانات أو الاتصال بقاعدة البيانات.</div><p class="muted">راجع README-AR.md لمعرفة خطوات الربط والقواعد.</p></div><div class="login-art"><h2>منيو مطعمك،<br>بأسلوب جديد.</h2><p>MenuCraft IQ — Rebuild</p></div></div>`;return}try{const fb=initializeApp(firebaseConfig);db=getFirestore(fb);auth=getAuth(fb);if(params.has('r')||params.has('menu')){await publicInit(params.get('r')||params.get('menu'));return}onAuthStateChanged(auth,async u=>{unsubOrders?.();orderGeneration++;document.querySelectorAll('[data-order-toast]').forEach(n=>n.remove());user=u;soundEnabled=readSound();membership=null;menus=[];orders=[];selected='';current=null;view='dashboard';if(!u){login();return}try{if(!isAdmin()){const a=await getDoc(doc(db,'restaurantAccounts',u.uid));membership=a.data();if(!a.exists()||membership.uid!==u.uid||membership.role!=='restaurant_owner'||membership.active!==true||!membership.menuId)throw Error('الحساب غير مفعل أو غير مرتبط بمطعم');}await loadMenus();renderAdmin()}catch(e){console.error(e);await signOut(auth);login();$('#authError').textContent='تعذر فتح لوحة التحكم: '+e.message}})}catch(e){error(e)}}
function login(){app.innerHTML=`<div class="login-wrap"><div class="login-card">${brand}<h1>أهلاً بعودتك 👋</h1><p class="muted">سجل الدخول لإدارة المطاعم والطلبات والمنيو.</p><form id="loginForm"><label>البريد الإلكتروني</label><input type="email" id="email" required autocomplete="username" dir="ltr"><label>كلمة المرور</label><input type="password" id="password" required autocomplete="current-password" dir="ltr"><p id="authError" style="color:#b62920"></p><button class="btn" style="width:100%;margin-top:18px">تسجيل الدخول</button></form></div><div class="login-art"><h2>منيو رقمي.<br>إدارة أسهل.<br>طلبات أسرع.</h2><p>لوحة تحكم MenuCraft IQ الجديدة</p></div></div>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();try{await signInWithEmailAndPassword(auth,$('#email').value,$('#password').value)}catch(err){$('#authError').textContent='فشل تسجيل الدخول: '+err.message}}}
async function loadMenus(){if(isAdmin()){const snap=await getDocs(query(collection(db,'menus'),where('owner','==',user.uid)));menus=snap.docs.map(d=>({...d.data(),id:d.id}));}else{const snap=await getDoc(doc(db,'menus',membership.menuId));if(!snap.exists())throw Error('المطعم غير موجود');menus=[{...snap.data(),id:snap.id}];}if(!menus.find(m=>m.id===selected))selected=menus[0]?.id||'';current=menus.find(m=>m.id===selected)?normalize(menus.find(m=>m.id===selected)):null;await loadOrders()}
let unsubOrders, orderGeneration=0, audioContext;
let soundEnabled=false;
function soundKey(){return 'mc-order-sound:'+user?.uid}
function readSound(){try{return localStorage.getItem(soundKey())==='1'}catch{return false}}
function playOrderSound(){if(!soundEnabled||audioContext?.state!=='running')return;try{const t=audioContext.currentTime;[660,880,1040].forEach((hz,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.frequency.value=hz;g.gain.setValueAtTime(0,t+i*.19);g.gain.linearRampToValueAtTime(.16,t+i*.19+.025);g.gain.exponentialRampToValueAtTime(.001,t+i*.19+.17);o.connect(g);g.connect(audioContext.destination);o.start(t+i*.19);o.stop(t+i*.19+.18)})}catch(e){console.warn('audio',e)}}
function updateOrderBadge(){const b=$('#orderBadge');if(b)b.textContent='طلبات جديدة: '+orders.filter(o=>o.status==='new').length;const s=$('#orderSound');if(s)s.textContent=soundEnabled&&audioContext?.state==='running'?'🔔 كتم الصوت':'🔕 تشغيل الصوت'}
async function toggleOrderSound(){try{if(soundEnabled&&audioContext?.state==='running'){soundEnabled=false}else{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();await audioContext.resume();soundEnabled=audioContext.state==='running';if(!soundEnabled)throw Error('الصوت غير متاح');playOrderSound()}try{localStorage.setItem(soundKey(),soundEnabled?'1':'0')}catch{}updateOrderBadge()}catch(e){soundEnabled=false;updateOrderBadge();notify('تعذر تشغيل الصوت، حاول مرة أخرى')}}
function orderToast(o){const n=document.createElement('div');n.setAttribute('role','status');n.style.cssText='position:fixed;bottom:24px;inset-inline-end:20px;z-index:9999;background:#14283d;color:white;padding:16px;border-radius:12px;max-width:calc(100vw - 40px);box-shadow:0 8px 30px #0004;cursor:pointer';n.textContent='🔔 طلب جديد #'+String(o.id).slice(0,8)+' • '+Number(o.total||0).toLocaleString('en-US')+' د.ع • '+(o.type==='delivery'?'توصيل':'استلام');n.onclick=()=>{n.remove();view='orders';renderAdmin()};document.body.append(n);n.dataset.orderToast='1';setTimeout(()=>n.remove(),8000)}
async function loadOrders(){unsubOrders?.();const generation=++orderGeneration;orders=[];updateOrderBadge();if(!selected||!(can('manageOrders')||can('viewReports')))return;let initialized=false;const seen=new Set();unsubOrders=onSnapshot(query(collection(db,'menus',selected,'orders')),{includeMetadataChanges:true},snap=>{if(generation!==orderGeneration||!user)return;orders=snap.docs.map(d=>({ ...d.data(),id:d.id})).sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0));if(!snap.metadata.fromCache){const incoming=initialized?orders.filter(o=>o.status==='new'&&!seen.has(o.id)):[];orders.forEach(o=>seen.add(o.id));initialized=true;if(incoming.length){orderToast(incoming[0]);if(incoming.length>1)notify('طلبات جديدة: '+incoming.length);playOrderSound()}}updateOrderBadge();if(view==='orders'||view==='dashboard'||view==='reports')drawPanel()},e=>{if(generation!==orderGeneration)return;orders=[];updateOrderBadge();if(view==='orders'||view==='dashboard'||view==='reports')drawPanel();notify('تعذر متابعة الطلبات');console.warn('orders',e)})}

