if(view==='restaurants'){panel.innerHTML=`<div class="panel"><div class="toolbar"><h2>مطاعمي (${menus.length})</h2><button class="btn" id="createMenu">+ مطعم جديد</button></div>${menus.map(m=>`<div class="listrow"><div><b>${safe(name(m.name,'ar'))}</b><small>${safe(m.id)}</small></div><div class="row-actions"><button class="mini" data-select="${safe(m.id)}">إدارة</button><a class="mini" href="?r=${encodeURIComponent(m.id)}" target="_blank">عرض المنيو</a></div></div>`).join('')||'<p class="muted">لا توجد مطاعم بعد.</p>'}</div>`;$('#createMenu').onclick=async()=>{let m={...fresh(),active:false,expiryAt:new Date(0),expires:'1970-01-01'},key=id();await setDoc(doc(db,'menus',key),m);selected=key;await loadMenus();view='settings';renderAdmin()};panel.querySelectorAll('[data-select]').forEach(b=>b.onclick=async()=>{selected=b.dataset.select;await loadMenus();view='items';renderAdmin()})}
if(view==='items'){if(!current){panel.innerHTML=requireMenu();return}panel.innerHTML=`<div class="panel"><div class="toolbar"><h2>الأقسام والوجبات</h2><div class="row-actions"><button class="btn secondary" id="addCat">+ قسم</button><button class="btn" id="addItem">+ وجبة</button></div></div>${current.categories.map((c,ci)=>`<div class="panel" style="background:#fafbfd"><div class="toolbar"><h3>${safe(name(c.name,'ar'))}</h3><div class="row-actions"><button class="mini" data-cat-edit="${ci}">تعديل القسم</button><button class="mini" data-cat-del="${ci}">حذف</button></div></div>${(c.items||[]).map((i,ii)=>`<div class="listrow"><div><b>${safe(name(i.name,'ar'))}</b><small>${money(i.price)} · ${i.available===false?'غير متوفر':'متوفر'}</small></div><div class="row-actions"><button class="mini" data-item-edit="${ci}:${ii}">تعديل</button><button class="mini" data-item-del="${ci}:${ii}">حذف</button></div></div>`).join('')||'<p class="muted">لا توجد وجبات في هذا القسم.</p>'}</div>`).join('')||'<p class="muted">ابدأ بإضافة قسم جديد.</p>'}</div>`;$('#addCat').onclick=()=>editCategory();$('#addItem').onclick=()=>editItem();panel.querySelectorAll('[data-cat-edit]').forEach(b=>b.onclick=()=>editCategory(+b.dataset.catEdit));panel.querySelectorAll('[data-cat-del]').forEach(b=>b.onclick=async()=>{if(confirm('حذف القسم وكل وجباته؟')){current.categories.splice(+b.dataset.catDel,1);await saveCurrent()}});panel.querySelectorAll('[data-item-edit]').forEach(b=>b.onclick=()=>{let [a,z]=b.dataset.itemEdit.split(':').map(Number);editItem(a,z)});panel.querySelectorAll('[data-item-del]').forEach(b=>b.onclick=async()=>{let [a,z]=b.dataset.itemDel.split(':').map(Number);if(confirm('حذف الوجبة؟')){current.categories[a].items.splice(z,1);await saveCurrent()}})}
