 $('#newCoupon').onclick=()=>editCoupon(menuId,null);panel.querySelectorAll('[data-coupon-edit]').forEach(b=>b.onclick=()=>editCoupon(menuId,rows.find(c=>c.code===b.dataset.couponEdit)));
